[Thinking]
**Exploring Excel options**

I need to find a suitable way to handle xlsx files since Qt doesn't read them natively. I have some options: I could use QAxObject for Excel automation on Windows or consider libxlsxwriter. I want to convert xls/xlsx files efficiently. So, using Qt5's C++ GUI, I'd pick a directory, create an output folder, and iterate through the files to save them as CSV. It seems better to export each worksheet as a separate CSV, especially if there are multiple sheets. I definitely need the code for this!
[/Thinking]

Below is a simple Qt5/C++ GUI program that lets the user select a directory, finds Microsoft Excel files in that directory, and converts them to CSV files in a new subfolder.

This example uses Microsoft Excel via COM automation, so it is Windows-only and requires Microsoft Excel to be installed.

It supports files such as:

```text
.xls
.xlsx
.xlsm
.xlsb
```

For workbooks with multiple sheets, it creates one CSV per sheet.

---

## Project file: `ExcelToCsv.pro`

```pro
QT += widgets axcontainer

CONFIG += c++11

SOURCES += main.cpp
```

---

## Source file: `main.cpp`

```cpp
#include <QApplication>
#include <QWidget>
#include <QPushButton>
#include <QVBoxLayout>
#include <QFileDialog>
#include <QMessageBox>
#include <QDir>
#include <QFileInfo>
#include <QLabel>
#include <QTextEdit>
#include <QAxObject>
#include <QRegularExpression>

class ExcelToCsvWindow : public QWidget
{
    Q_OBJECT

public:
    ExcelToCsvWindow(QWidget *parent = nullptr)
        : QWidget(parent)
    {
        setWindowTitle("Excel to CSV Converter");
        resize(500, 300);

        QLabel *label = new QLabel(
            "Select a folder containing Microsoft Excel files.\n"
            "CSV files will be written into a new folder inside it."
        );

        QPushButton *button = new QPushButton("Select Folder and Convert");

        logBox = new QTextEdit();
        logBox->setReadOnly(true);

        QVBoxLayout *layout = new QVBoxLayout();
        layout->addWidget(label);
        layout->addWidget(button);
        layout->addWidget(logBox);

        setLayout(layout);

        connect(button, &QPushButton::clicked,
                this, &ExcelToCsvWindow::selectFolderAndConvert);
    }

private slots:
    void selectFolderAndConvert()
    {
        QString directoryPath = QFileDialog::getExistingDirectory(
            this,
            "Select Folder Containing Excel Files"
        );

        if (directoryPath.isEmpty())
            return;

        convertExcelFiles(directoryPath);
    }

private:
    QTextEdit *logBox;

    void log(const QString &message)
    {
        logBox->append(message);
        QApplication::processEvents();
    }

    QString sanitizeFileName(const QString &name)
    {
        QString result = name;

        // Remove characters invalid in Windows filenames
        result.replace(QRegularExpression("[\\\\/:*?\"<>|]"), "_");

        return result;
    }

    void convertExcelFiles(const QString &directoryPath)
    {
        QDir inputDir(directoryPath);

        if (!inputDir.exists()) {
            QMessageBox::critical(this, "Error", "Selected directory does not exist.");
            return;
        }

        QString outputFolderName = "converted_csv";
        QString outputDirPath = inputDir.filePath(outputFolderName);

        QDir outputDir(outputDirPath);
        if (!outputDir.exists()) {
            if (!inputDir.mkdir(outputFolderName)) {
                QMessageBox::critical(this, "Error", "Could not create output folder.");
                return;
            }
        }

        QStringList filters;
        filters << "*.xls" << "*.xlsx" << "*.xlsm" << "*.xlsb";

        QFileInfoList excelFiles = inputDir.entryInfoList(
            filters,
            QDir::Files | QDir::NoSymLinks
        );

        if (excelFiles.isEmpty()) {
            QMessageBox::information(this, "No Files", "No Excel files were found.");
            return;
        }

        log("Starting Microsoft Excel...");

        QAxObject excel("Excel.Application");

        if (excel.isNull()) {
            QMessageBox::critical(
                this,
                "Error",
                "Could not start Microsoft Excel.\n"
                "Make sure Microsoft Excel is installed."
            );
            return;
        }

        excel.setProperty("Visible", false);
        excel.setProperty("DisplayAlerts", false);

        QAxObject *workbooks = excel.querySubObject("Workbooks");

        int convertedCount = 0;

        for (const QFileInfo &fileInfo : excelFiles) {
            QString excelFilePath = QDir::toNativeSeparators(fileInfo.absoluteFilePath());

            log("Opening: " + fileInfo.fileName());

            QAxObject *workbook = workbooks->querySubObject(
                "Open(const QString&)",
                excelFilePath
            );

            if (!workbook || workbook->isNull()) {
                log("  Failed to open file.");
                delete workbook;
                continue;
            }

            QAxObject *worksheets = workbook->querySubObject("Worksheets");
            int sheetCount = worksheets->property("Count").toInt();

            for (int i = 1; i <= sheetCount; ++i) {
                QAxObject *sheet = worksheets->querySubObject("Item(int)", i);

                if (!sheet || sheet->isNull()) {
                    delete sheet;
                    continue;
                }

                QString sheetName = sheet->property("Name").toString();

                QString baseName = fileInfo.completeBaseName();
                QString csvFileName = sanitizeFileName(baseName + "_" + sheetName + ".csv");
                QString csvFilePath = QDir::toNativeSeparators(
                    outputDir.filePath(csvFileName)
                );

                log("  Exporting sheet: " + sheetName);

                sheet->dynamicCall("Activate()");

                /*
                    Excel FileFormat value for CSV:
                    6 = xlCSV

                    This saves the active sheet as a CSV.
                */
                workbook->dynamicCall(
                    "SaveAs(const QString&, int)",
                    csvFilePath,
                    6
                );

                convertedCount++;

                delete sheet;
            }

            workbook->dynamicCall("Close(bool)", false);

            delete worksheets;
            delete workbook;
        }

        excel.dynamicCall("Quit()");

        log("");
        log("Done.");
        log("CSV files written to:");
        log(outputDirPath);

        QMessageBox::information(
            this,
            "Conversion Complete",
            QString("Converted %1 worksheet(s) to CSV.\n\nOutput folder:\n%2")
                .arg(convertedCount)
                .arg(outputDirPath)
        );
    }
};

#include "main.moc"

int main(int argc, char *argv[])
{
    QApplication app(argc, argv);

    ExcelToCsvWindow window;
    window.show();

    return app.exec();
}
```

---

## Build Notes

This program requires the Qt ActiveX container module:

```pro
QT += axcontainer
```

That means it works with MSVC or MinGW on Windows, but Microsoft Excel must be installed on the machine.

---

## Output Example

If the selected folder contains:

```text
C:/Data/report.xlsx
C:/Data/budget.xls
```

The program creates:

```text
C:/Data/converted_csv/
```

And outputs files such as:

```text
report_Sheet1.csv
report_Sheet2.csv
budget_Summary.csv
```

Each worksheet is exported as a separate CSV file.

